import {taskStatus,taskTime} from './tasks.js';
import {VERSION,DAY,HOUR,FAMILIES,RARITIES,RARITY_COLORS,ROOMS,TRAITS,JOBS,LEAGUES,STATS,ACHIEVEMENTS,AFFIXES} from './data.js';
import * as M from './model.js';
import * as C from './combat.js';
import {advanceCombatPlayback,COMBAT_SPEEDS} from './playback.js';
import {startCombatArena,arenaTheme} from './arena.js';
import * as L from './sports.js';
import * as T from './simulation.js';
import * as P from './persistence.js';
import {esc,portrait,roomArt,castleArt,startScene} from './academy.js';
let s=null,route=null,modalEpoch=0,busy=false,lastTick=performance.now(),localAt=0,cloudAt=0,lastRail=0,toastTimer,archivePage=null,historyWizard=null,watch={id:null,index:0,playing:false,at:0},inventory={family:'',rarity:'',slot:'',owner:'',sort:'power',search:'',page:0},recordFilters={metric:'depth',status:'All-Time'},archiveType='wizards',archiveCursor='',leagueView=0,authMode='login';
const $=id=>document.getElementById(id),n=x=>Math.floor(x||0).toLocaleString(),fmt=x=>Number(x||0).toLocaleString(undefined,{maximumFractionDigits:1}),duration=x=>x<60000?`${Math.ceil(Math.max(0,x)/1000)}s`:x<HOUR?`${Math.ceil(x/60000)}m`:`${(x/HOUR).toFixed(1)}h`,family=id=>FAMILIES.find(f=>f.id===id),button=(label,action,data='',cls='')=>`<button class="${cls}" data-act="${action}" ${data}>${label}</button>`,metric=(label,value)=>`<div class="metric"><strong>${value}</strong><span>${label}</span></div>`,empty=t=>`<div class="empty">${t}</div>`,section=t=>`<div class="section-title"><h3>${t}</h3></div>`,options=(rows,value)=>rows.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join(''),tag=t=>`<span class="tag">${esc(t)}</span>`;
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),5000);}
function download(text,name){const u=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function errorMessage(e){const code=e.code||'';if(code.includes('invalid-credential'))return 'Email or password was not recognized.';if(code.includes('email-already-in-use'))return 'That email already has an account. Choose Sign in.';if(code.includes('weak-password'))return 'Use a password of at least six characters.';if(code.includes('operation-not-allowed'))return 'Enable Email/Password in Firebase Authentication, then try again.';if(code.includes('permission-denied'))return 'Firestore denied access. Publish the included firestore.rules in your Firebase console.';if(code.includes('unauthorized-domain'))return 'Add your GitHub Pages domain to Firebase Authentication → Settings → Authorized domains.';return e.message||'Something went wrong. Your last saved progress is safe.';}
async function checkpoint(cloud=false){if(!s)return;try{await P.saveLocal(s);if(cloud&&P.account!=='local')await P.saveCloud(s);}catch(e){toast(errorMessage(e));}updateHUD();}
function authScreen(){s=null;route=null;$('panel').close();$('app').innerHTML=`<main class="auth-page"><section class="auth-art"><span class="crest">✦</span><div class="eyebrow">A generational academy management game</div><h1>Small beginnings.<br>Extraordinary<br>histories.</h1><p>Five beds. A questionable dungeon. An institution that will outlive everyone who builds it.</p><div class="mini-castle">${castleArt()}</div><p class="fineprint" style="margin-top:24px">WIZARD ACADEMY &nbsp; / &nbsp; ${VERSION}</p></section><section class="auth-card-wrap"><div class="auth-card"><div class="eyebrow" style="color:#a88c56">The headmaster’s office</div><h2>${authMode==='signup'?'Begin your legacy':'Welcome, Headmaster.'}</h2><p class="muted">${authMode==='signup'?'Your academy starts with a name.':'Your institution is waiting for you.'}</p><form id="auth-form"><label>Email address<input id="email" type="email" autocomplete="email" required placeholder="headmaster@academy.edu"></label><label>Password<input id="password" type="password" autocomplete="${authMode==='signup'?'new-password':'current-password'}" minlength="6" required placeholder="At least six characters"></label><button type="submit">${authMode==='signup'?'Create account':'Sign in'} <span aria-hidden="true">→</span></button></form>${button(authMode==='signup'?'Already enrolled? Sign in':'New here? Create an account','auth-toggle','','secondary')}${button('Forgot password?','reset-password','','secondary')}${button('Play locally on this device','local','','secondary')}<p class="fineprint" style="margin-top:15px">Cloud accounts save across devices. Local play stays in this browser; export backups from the Front Desk.</p><p id="auth-status" class="auth-status" role="alert"></p></div></section></main>`;}
function foundScreen(){route=null;$('app').innerHTML=`<main class="auth-page"><section class="auth-art"><div class="eyebrow">An institution in the making</div><h1>What will they<br>remember?</h1><p>Not every wizard will be a legend. Every wizard will have a story.</p><div class="mini-castle">${castleArt()}</div></section><section class="auth-card-wrap"><div class="auth-card"><h2>Found your academy</h2><p class="muted">An empty building. Five beds. Your first generation has not yet arrived.</p><form id="found-form"><label>Academy name<input id="academy-name" maxlength="48" required placeholder="The Wayward Academy" value="The Wayward Academy"></label><button>Sign the founding charter</button></form><div class="note">One real day is one Academy Year. Up to twelve hours of idle progress await your return. Unknown dungeon floors always require your decision.</div><p class="fineprint">${P.account==='local'?'Local academy · saved in this browser':'Cloud academy · saved to your account'}</p></div></section></main>`;}
async function enterAccount(id){if(!await P.lockAccount(id))throw Error('This academy is already open in another tab. Close that tab, then try again.');s=await P.load(id);localStorage.setItem('wa-mode',id==='local'?'local':'cloud');if(!s){foundScreen();return;}if(s.schema!==1)throw Error('Unsupported save schema. Update the game files.');if(s.combat&&!COMBAT_SPEEDS.includes(s.combat.speed))s.combat.speed=1;const report=T.processTime(s);leagueView=L.playerSchool(s).league;renderMain();await checkpoint();if(report.elapsed>120000)showReport(report);}
function renderMain(){if(!s)return;const yr=M.year(s),frac=s.time%DAY/DAY,open=s.intro,chat=s.chat[0];$('app').innerHTML=`<header class="topbar"><div class="brand"><span class="crest" aria-hidden="true">✦</span><div><div class="eyebrow">Wizard Academy</div><h1>${esc(s.name)}</h1></div></div><div class="resources" id="resources"></div></header><div class="layout"><main class="main-school"><div class="school-heading"><div><h2>The academy grounds</h2><p>${s.prestige<25?'A little rough around the edges. Just like its students.':s.prestige<100?'The walls are growing. So is the legend.':'Built by generations. Remembered for centuries.'}</p></div><div class="year-chip" id="year-chip">YEAR ${yr}<span>${['Early','Mid','Late'][Math.min(2,Math.floor(frac*3))]} term</span></div></div>${!open?`<div class="onboarding-banner"><h3>The keys are yours.</h3><p>Your charter is signed. Open the front desk, dormitory, storage, archives, and dungeon entrance to receive your first applicants.</p>${button('Open the academy','open-foundation','','gold')}</div>`:M.active(s).length===0?`<div class="onboarding-banner"><h3>${s.stats.recruited?'The academy can begin again.':'The founding generation is waiting.'}</h3><p>Tap the Front Desk to recruit your first wizards. Open the Practice Hall, Rune Chamber, and Arcane Rift when you are ready.</p>${button('Meet the applicants','room','data-room="desk"','gold')}</div>`:''}<div class="school-scene"><div class="room-grid">${ROOMS.map(r=>{const lv=s.rooms[r.id];return `<button class="room ${lv?'':'locked'}" data-act="room" data-room="${r.id}" aria-label="${esc(r.name)} — ${esc(r.sub)}${lv?'':', unopened'}">${lv?roomArt(r.id,lv):`<div class="blueprint"><div>${r.icon}<small>${lv?'':s.prestige<r.prestige?r.prestige+' Prestige':'Room for possibility'}</small></div></div>`}<span class="room-label">${esc(r.name)}<b>${lv?'ⅠⅡⅢⅣⅤⅥ'[lv-1]:'＋'}</b></span>${r.id==='desk'&&s.applicants.length?`<span class="room-badge">${s.applicants.length}</span>`:r.id==='gate'&&s.expedition?'<span class="room-badge">!</span>':''}</button>`;}).join('')}</div><canvas class="scene-canvas" aria-hidden="true"></canvas><div class="walkway">The institution remains</div></div><div class="scene-hint"><span>Tap a room to manage it · Every wizard has a story</span><span id="save-status">${esc(P.cloudStatus)}</span></div><div class="bottom-progress"><span class="symbol">◈</span><p><strong id="depth-line">${s.depth?'Deepest descent · Floor '+s.depth:'Belowstairs awaits'}</strong><br>${s.expedition?'An expedition is outside. Tap the dungeon gate to return to it.':'The next floor is always your decision. Nobody advances without you.'}</p></div></main><aside class="side-rail" id="rail"></aside></div>`;updateHUD();renderRail();}
function updateHUD(){if(!s||!$('resources'))return;$('resources').innerHTML=[['Gold','◌ '+n(s.gold)],['Prestige','✦ '+fmt(s.prestige)],['Wizards',M.active(s).length+' / '+M.capacity(s)],['Boss seals','◈ '+n(s.seals)]].map(([k,v])=>`<div class="resource"><span>${k}</span><strong>${v}</strong></div>`).join('');$('save-status').textContent=P.cloudStatus;$('year-chip').innerHTML=`YEAR ${M.year(s)}<span>${['Early','Mid','Late'][Math.floor((s.time%DAY/DAY)*3)]} term</span>`;}
function renderRail(){if(!s||!$('rail'))return;const chat=s.chat[0],fixture=L.nextFixture(s),pending=s.events[0];$('rail').innerHTML=`<section><div class="rail-title">The noticeboard <span>Office dispatch</span></div><div class="notice"><div class="eyebrow" style="font-size:8px">${pending?'A decision awaits':'Your next chapter'}</div><h4>${pending?esc(pending.title):s.stats.recruited<5?'Five beds. Five beginnings.':s.depth===0?'A door beneath the school.':!s.rooms.runes?'A little magical industry.':'The academy is in motion.'}</h4><p>${pending?esc(pending.body):s.stats.recruited<5?'Your founding generation is waiting at Admissions. Choose who gets the first key.':s.depth===0?'Choose up to three wizards at Belowstairs. Their first expedition will be remembered.':!s.rooms.runes?'Open the Rune Chamber. Equipment is powerful; somebody must keep it supplied.':'Train, produce, prepare. Tomorrow’s legends are today’s difficult students.'}</p>${button(pending?'Review the matter →':s.stats.recruited<5?'Visit Admissions →':s.depth===0?'Visit Belowstairs →':'Visit Front Desk →',pending?'events':'room',pending?'':`data-room="${s.stats.recruited<5?'desk':s.depth===0?'gate':'desk'}"`)}</div></section><section><div class="rail-title">Overheard <span>In the corridors</span></div><div class="conversation">“${esc(chat?.text||'Do we actually have permission to open an academy here?')}”</div><div class="speaker">${esc(chat?.name||'The admissions clerk')}${chat?.to?' · to '+esc(chat.to):''}</div></section><section><div class="rail-title">Academy chronicle <span>Year ${M.year(s)}</span></div><div class="rail-feed">${s.feed.slice(0,4).map(e=>`<div class="feed-item"><div class="date">YEAR ${e.year} / ${esc(e.kind.toUpperCase())}</div><p>${esc(e.text)}</p></div>`).join('')}</div></section><div class="sidebar-footer">${esc(LEAGUES[L.playerSchool(s).league])} · Next: ${esc(fixture.label)}<br>In ${duration(fixture.at-s.time)} · 24 hours per Academy Year<br><span class="fineprint">Wizard Academy ${VERSION} · The first charter</span></div>`;}
function panel(title,sub,content){const dlg=$('panel'),existingCanvas=route?.type==='combat'?$('combat-canvas'):null;$('panel-head').innerHTML=`<div><div class="eyebrow">${esc(sub)}</div><h2>${esc(title)}</h2></div>${button('×','close','aria-label="Close panel"')}`;$('panel-body').innerHTML=`<div class="tab-content${route?.type==='combat'?' combat-content':''}${content.includes('data-task=')?' task-content':''}">${content}</div>`;if(existingCanvas&&existingCanvas.tagName==='CANVAS'){const replacement=$('panel-body').querySelector('#combat-canvas');if(replacement)replacement.replaceWith(existingCanvas);}if(!dlg.open)dlg.showModal();}
function tabs(items,selected){return `<div class="tabs">${items.map(([id,label])=>button(label,'tab',`data-tab="${id}"`,selected===id?'active':'')).join('')}</div>`;}
function openRoom(id,tab){historyWizard=null;archivePage=null;archiveCursor='';route={type:'room',id,tab:tab||({desk:'applicants',dorm:'roster',storage:'items',rift:'league',archives:'records',hall:'legends'}[id]||'main')};renderPanel();}
function wizardCard(w,applicant=false){const a=M.attributes(s,w);return `<article class="card"><div class="card-header">${portrait(w)}<div><h3>${esc(w.name)}</h3><p>Age ${M.age(s,w)} · ${applicant?'Applicant':esc(w.status)+' · Level '+w.level}</p></div></div><div class="chips">${w.founder?'<span class="tag founder">Founding generation</span>':''}${tag(TRAITS[w.trait][0])}${tag('Rift potential '+w.potential)}${w.hof?tag('Hall of Fame'):''}</div><p>${esc(TRAITS[w.trait][1])}</p><div class="metrics">${metric('Health',a.hp)}${metric('Mana',a.mana)}${metric('Power',a.power)}${metric('Rift LV',w.sportLevel)}</div>${!applicant&&w.status==='Active'?taskMarkup(w):''}${applicant?`<p class="fineprint">Application held for ${duration(w.expires-s.time)}. No recruitment fee.</p><div class="actions">${button('Offer a place','recruit',`data-id="${w.id}" ${M.active(s).length>=M.capacity(s)?'disabled':''}`)}${button('View profile','wizard',`data-id="${w.id}"`,'secondary')}</div>`:`<p>${w.injury?'✚ '+esc(w.injury.name):esc(JOBS[w.job]||w.job)} ${s.expedition?.ids.includes(w.id)?'· On expedition':''}</p><div class="bar"><i style="width:${Math.max(0,Math.min(100,w.hp/a.hp*100))}%"></i></div><div class="vitals"><span>${Math.round(w.hp||0)} / ${a.hp} HP</span><span>${Math.round(w.mana||0)} / ${a.mana} mana</span></div><div class="actions">${button('Meet '+esc(w.name.split(' ')[0]),'wizard',`data-id="${w.id}"`,'secondary')}</div>`}</article>`;}
function facilityHeader(id){const r=ROOMS.find(r=>r.id===id),lv=s.rooms[id],cost=lv?Math.round((r.cost||140)*Math.pow(2.15,lv)):r.cost,req=r.prestige+lv*8;return `<div class="note"><strong>${lv?'Tier '+lv+' facility':'Unopened wing'}</strong> · ${lv>=6?'Architectural potential fulfilled.':`${n(cost)} gold · ${req} Prestige required`}<div class="actions" style="margin-top:10px">${lv<6?button(lv?'Expand facility':'Open this room','upgrade',`data-id="${id}" ${s.gold<cost||s.prestige<req?'disabled':''}`):''}</div></div>`;}
function facultyPanel(id){if(!['training','runes','infirmary','rift','garden','observatory','archives'].includes(id))return '';const retirees=s.wizards.filter(w=>['Retired','Faculty'].includes(w.status));const current=s.wizards.find(w=>w.id===s.faculty[id]);return `${section('The professor’s desk')}<p class="panel-intro">One faculty member per facility. Bonuses reflect their lived career. Professors eventually pass away; their record never does.</p><label>Appoint faculty<select data-change="faculty" data-room="${id}">${options([['','No professor assigned'],...retirees.map(w=>[w.id,w.name+' · age '+M.age(s,w)])],s.faculty[id]||'')}</select></label>${current?`<div class="note">${esc(current.name)} · +${Math.round((M.bonus(s,id)-1)*100)}% effectiveness. ${button('View career','wizard',`data-id="${current.id}"`,'secondary small')}</div>`:''}`;}
function taskMarkup(w){const t=taskStatus(s,w);return `<div class="task-progress" data-task="${w.id}"><div class="task-heading"><strong data-task-label>${esc(t.label)}</strong><span data-task-time>${t.blocked?'Waiting':t.remaining===null?'':t.remaining<=0?(w.job==='rest'||w.job==='recovery'?'Ready':'Completing…'):taskTime(t.remaining)+' remaining'}</span></div><div class="task-track" role="progressbar" aria-label="${esc(t.label)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(t.fraction*100)}"><i style="width:${t.fraction*100}%"></i></div><p data-task-detail>${esc(t.detail)}</p><small data-task-cycle>${t.cycle?'Each cycle: '+taskTime(t.cycle)+' · repeats automatically':''}</small></div>`;}
function updateTaskViews(){for(const el of document.querySelectorAll('[data-task]')){const w=s.wizards.find(w=>w.id===el.dataset.task);if(!w)continue;const t=taskStatus(s,w,Math.max(0,Date.now()-s.lastWall)/1000),percent=Math.max(0,Math.min(100,t.fraction*100));el.classList.toggle('waiting',t.blocked);el.querySelector('[data-task-label]').textContent=t.label;el.querySelector('[data-task-time]').textContent=t.blocked?'Waiting':t.remaining===null?'':t.remaining<=0?(w.job==='rest'||w.job==='recovery'?'Ready':'Completing…'):taskTime(t.remaining)+' remaining';el.querySelector('.task-track i').style.width=percent+'%';el.querySelector('.task-track').setAttribute('aria-valuenow',String(Math.round(percent)));el.querySelector('[data-task-detail]').textContent=t.detail;el.querySelector('[data-task-cycle]').textContent=t.cycle?'Each cycle: '+taskTime(t.cycle)+' · repeats automatically':'';}}
function assignmentPanel(jobs){return M.active(s).length?M.active(s).map(w=>{const choices=[['rest',JOBS.rest],...jobs.map(j=>[j,JOBS[j]])];if(!choices.some(([j])=>j===w.job))choices.push([w.job,JOBS[w.job]]);return `<div class="assignment-row"><div class="list-row"><div class="name"><strong>${esc(w.name)}</strong><br><small>Level ${w.level}${w.injury?' · injured':''}${s.expedition?.ids.includes(w.id)?' · outside':''}</small></div><select aria-label="Assignment for ${esc(w.name)}" data-change="job" data-id="${w.id}" ${s.expedition?.ids.includes(w.id)?'disabled':''}>${options(choices,w.job)}</select></div>${taskMarkup(w)}</div>`;}).join(''):empty('Recruit your first wizards at the Front Desk.');}
function renderPanel(){if(!route||!s)return;modalEpoch++;if(route.type==='wizard'){renderWizard();return;}if(route.type==='item'){renderItem();return;}if(route.type==='combat'){renderCombat();return;}if(route.type==='events'){renderEvents();return;}if(route.type==='match'){renderMatch();return;}if(route.type==='season'){renderSeason();return;}const id=route.id,r=ROOMS.find(r=>r.id===id),tab=route.tab;let html='';if(!s.rooms[id]){panel(r.name,r.sub,`<p class="panel-intro">${{training:'A place to aim spells at things that have consented.',runes:'The quiet industry behind spectacular magic. Unscribed stones become twelve charges of a chosen rune.',rift:'Two Strikers. One Controller. Two Wardens. An entire league to annoy.',infirmary:'The bed linen is clean. The prognosis is occasionally sarcastic.',hall:'Build a home for the names that define your academy.',garden:'Potion ingredients grow best when nobody makes eye contact.',observatory:'Trade runestones and patient work for lasting Prestige.'}[id]||'The academy begins with one decision.'}</p>${facilityHeader(id)}`);return;}
 if(id==='desk'){html=tabs([['applicants','Admissions'],['office','Office'],['events','Decisions'],['settings','Settings & save'],['guide','Headmaster’s handbook']],tab);if(tab==='applicants')html+=`<p class="panel-intro">A new pool arrives every Academy Year. Applications remain for three years. Prestige attracts more promising candidates.</p><div class="metrics">${metric('Available beds',M.capacity(s)-M.active(s).length)}${metric('Applicants',s.applicants.length)}${metric('Next intake',duration(DAY-s.time%DAY))}${metric('Prestige',fmt(s.prestige))}</div><div class="cards">${s.applicants.map(w=>wizardCard(w,true)).join('')||empty('The next applicants will arrive with the new Academy Year.')}</div>`;
 else if(tab==='office')html+=`<div class="metrics">${metric('Year',M.year(s))}${metric('Gold',n(s.gold))}${metric('Prestige',fmt(s.prestige))}${metric('Deepest floor',s.depth)}</div>${section('Academy wings')}<div class="cards">${ROOMS.map(r=>`<div class="card"><h3>${esc(r.name)}</h3><p>${esc(r.sub)}</p>${facilityHeader(r.id)}</div>`).join('')}</div>${section('Clerical work')}<p class="panel-intro">Earn a little gold by turning magical disasters into orderly files. No resource cost.</p>${assignmentPanel(['clerical'])}`;
 else if(tab==='events')html+=eventContent();
 else if(tab==='settings')html+=`<div class="note"><strong>${esc(P.cloudStatus)}</strong><br>${P.account==='local'?'This academy is stored on this browser only. Export backups before clearing browser data.':'Cloud sync uses your private UID. Saves synchronize about once a minute and on key decisions. Keep one device active at a time.'}</div><div class="actions">${button('Save now','save')}${button('Export complete backup','export','','secondary')}${button('Previous device snapshot','device-recovery','','secondary')}${button('Sign out','logout','','secondary')}</div>${P.conflicted?`<div class="note warning">Another device has newer progress. Export this session if needed, then reload. ${button('Reload cloud save','reload','','secondary')}</div>`:''}${section('Presentation')}<label>Academy & combat motion<select data-change="motion">${options([['yes','Living academy'],['no','Reduced motion']],s.settings.motion?'yes':'no')}</select></label>${P.account==='local'?`${section('Restore a local backup')}<p class="panel-intro">This replaces the local academy. Export it first if you want to keep it. Cloud saves are not overwritten.</p><label>Choose a Wizard Academy JSON backup<input id="import-file" type="file" accept="application/json,.json"></label>${button('Restore selected backup','import','','danger')}`:''}${section('Build information')}<p class="fineprint">Wizard Academy ${VERSION} · Save schema ${s.schema} · Cloud revision ${s.revision}<br>No runtime AI, no build step, no service-account credentials.<br>Clock progress is capped at 12 hours per return. For a longer absence, production, aging, and league schedules pause beyond that cap.</p>`;
 else html+=guide();}
 else if(id==='dorm'){html=`<p class="panel-intro">${M.active(s).length} active wizards · ${M.capacity(s)} beds. Equipment defines a build; nobody is born into a class.</p><div class="cards">${s.wizards.filter(w=>w.status!=='Deceased').map(w=>wizardCard(w)).join('')||empty('There is still room to make a first impression. Recruit at the Front Desk.')}</div>${facilityHeader(id)}`;}
 else if(id==='storage'){html=tabs([['items','Equipment'],['supplies','Supplies'],['vault','Deep storage'],['records','Item records']],tab);if(tab==='items')html+=inventoryContent();else if(tab==='supplies')html+=suppliesContent();else if(tab==='vault'){html+=`<p class="panel-intro">Shelved items retain their full rolls and provenance. Withdraw them to equip. Past discoveries and sold items also remain in this catalogue.</p><div id="archive-list">Opening the catalogue…</div>`;queueMicrotask(()=>loadHistory('items',true));}else html+=`<p class="panel-intro">The greatest rolls in each family. There is no perfect 100% roll and no designed maximum.</p><div class="cards">${Object.entries(s.itemRecords).map(([key,r])=>`<div class="card"><p>${esc(key.replace('_',' · ').toUpperCase())}</p><h3>${fmt(r.value)}</h3><p>${esc(r.name)} · Year ${r.year}</p>${tag(r.quality)}${button('Provenance','item-history',`data-id="${r.id}"`,'secondary small')}</div>`).join('')||empty('The first discovery will start your record book.')}</div>`;}
 else if(id==='training')html=`<p class="panel-intro">Training improves adventure level, HP, mana, and modest casting power. The spells themselves come from equipment. About 160 XP per hour before bonuses.</p>${assignmentPanel(['training','athletics'])}${facultyPanel(id)}${facilityHeader(id)}`;
 else if(id==='runes')html=`<p class="panel-intro">One unscribed rune becomes 12 spell charges. Boss Seals use 3 ingredients and 8 gold. Assign producers and inscribers separately. Advanced equipment consumes matching rune tiers.</p>${suppliesContent(false)}${section('Production assignments')}${assignmentPanel(['blank',...FAMILIES.map(f=>f.id),'seals'])}${section('Inscription tier')}<p class="fineprint">Tier II requires wizard level 10; tier III requires level 25. Advanced inscriptions take longer.</p>${M.active(s).filter(w=>FAMILIES.some(f=>f.id===w.job)).map(w=>`<div class="list-row"><strong>${esc(w.name)}</strong><select style="width:160px" data-change="rune-tier" data-id="${w.id}">${options([[1,'Tier I'],...(w.level>=10?[[2,'Tier II']]:[]),...(w.level>=25?[[3,'Tier III']]:[])],w.runeTier||1)}</select></div>`).join('')}${facultyPanel(id)}${facilityHeader(id)}`;
 else if(id==='infirmary')html=`<p class="panel-intro">All wizards slowly recover at home. Infirmary patients regain HP and mana much faster, and injuries heal sooner. No random treatment death.</p><div class="cards">${M.active(s).filter(w=>w.injury||w.hp<M.attributes(s,w).hp*.95).map(w=>`<div class="card"><div class="card-header">${portrait(w)}<div><h3>${esc(w.name)}</h3><p>${w.injury?esc(w.injury.name)+' · '+duration(w.injury.until-s.time):'Recovering from expedition'}</p></div></div><div class="actions">${button('Assign bed','assign-recovery',`data-id="${w.id}"`)}${button('Use potion','potion',`data-id="${w.id}"`,'secondary')}</div></div>`).join('')||empty('No patients. This is the preferred outcome.')}</div>${assignmentPanel(['recovery'])}${facultyPanel(id)}${facilityHeader(id)}`;
 else if(id==='gate')html=gateContent();
 else if(id==='rift')html=riftContent();
 else if(id==='archives'){html=tabs([['records','Record books'],['wizard-history','Wizard archives'],['timeline','Chronicle'],['seasons','Seasons'],['conversations','Conversations']],tab);if(tab==='records')html+=recordsContent();else if(tab==='seasons')html+=`<p class="panel-intro">Every completed year preserves all four leagues, standings, playoffs, movements, rosters, individual statistics, and match IDs.</p><label>Academy Year<input id="season-year" type="number" min="1" max="${Math.max(1,M.year(s)-1)}" value="${Math.max(1,M.year(s)-1)}"></label><div class="actions" style="margin-top:14px">${button('Open season','load-season')}</div>${M.year(s)===1?empty('The first season is still being written.'):''}`;else{const type=tab==='wizard-history'?'wizards':tab==='timeline'?'timeline':'conversations';html+=`<p class="panel-intro">Permanent records, loaded 30 at a time. ${type==='wizards'?'All attendees receive a record. Living careers are available from the Dormitory.':''}</p><div id="archive-list">Opening the archives…</div>`;queueMicrotask(()=>loadHistory(type,true));}}
 else if(id==='hall'){html=tabs([['legends','Hall of Names'],['achievements','Achievements']],tab);if(tab==='achievements')html+=`<div class="cards">${ACHIEVEMENTS.map(([id,name,desc,key,target,p])=>`<article class="card achievement ${s.achievements.includes(id)?'':'unearned'}"><span class="medal">${s.achievements.includes(id)?'✦':'◇'}</span><div><h3>${esc(name)}</h3><p>${esc(desc)}</p><small>${n(Math.min(s.stats[key]||0,target))} / ${n(target)} · ${p} Prestige</small></div></article>`).join('')}</div>`;else html+=`<p class="panel-intro">A wizard qualifies through 30 floors, 10 boss kills, 500 Rift goals, three championships, 10,000 runes, 30 years of service, or 5,000 healing. Induction is a one-time honor, never an endlessly stacking power bonus.</p><div class="cards">${s.wizards.filter(qualifies).map(w=>`<div class="card"><div class="card-header">${portrait(w)}<div><h3>${esc(w.name)}</h3><p>${w.hof?'Inscribed in the Hall of Names':'Eligible for induction'}</p></div></div>${button(w.hof?'Read their story':'Induct into the Hall',w.hof?'wizard':'induct',`data-id="${w.id}"`)}</div>`).join('')||empty('Legends take time. The archive is already keeping watch.')}</div>${section('The names we keep')}<div id="archive-list">Opening the memorial register…</div>${facilityHeader(id)}`;if(tab==='legends')queueMicrotask(()=>loadHistory('honors',true));}
 else if(id==='garden')html=`<p class="panel-intro">Brew a restorative potion for 6 gold. Potions restore 45% HP and 30% mana between floors. Baseline brewing takes seven minutes.</p>${assignmentPanel(['garden'])}${facultyPanel(id)}${facilityHeader(id)}`;
 else if(id==='observatory')html=`<p class="panel-intro">Trade 3 unscribed runes and fifteen minutes of research for 0.25 Prestige. A slow, dependable reputation beyond dungeon and sport.</p>${assignmentPanel(['research'])}${facultyPanel(id)}${facilityHeader(id)}`;
 panel(r.name,r.sub,html);}
function qualifies(w){return w.hof||(w.stats.depth||0)>=30||(w.stats.bossKills||0)>=10||(w.stats.goals||0)>=500||(w.stats.championships||0)>=3||(w.stats.runes||0)>=10000||(w.stats.healing||0)>=5000||(w.departure?w.departure.year-(Math.floor(w.joined/DAY)+1):(s.time-w.joined)/DAY)>=30;}
function guide(){return `<div class="cards">${[['A first week in one day','Recruit five wizards. Open the Practice Hall, Rune Chamber, and Rift facility. Train one or two, make blank runes with another, and field a sports lineup. Start on floor 1 with three healthy wizards. Magic Missile works without gear or runes.'],['Builds live in the chest','Every wizard has a focus, robe, and charm. Each item grants its family’s spell. Mix families to create hybrids. Supply matching rune charges; tier II spells need tier II charges. If charges or mana run out, Magic Missile remains available.'],['Decide how greedy to be','Each new floor stops after victory. HP and mana carry forward. Use potions between floors, advance deliberately, or return. A wizard at zero HP dies permanently. Lost equipment stays at that floor until recovered.'],['A school, not a waiting room','Training, rune manufacture, inscription, seal binding, potion brewing, clerical work, and research all progress while away. Farming uses real combat and can kill a weak party. Only assign it after preparing carefully.'],['The sport of Arcane Rift','Two Strikers propel a mote through a shifting aperture, a Controller creates passing lanes, and two Wardens defend. Risky passes can create two-point goals or turnovers. Safe passing reduces turnovers. Fast tempo creates more possessions. Defense and offense trade scoring against protection.'],['The annual calendar','Sixteen match windows fit into a 24-hour Academy Year: fourteen regular games, semifinals, and a final. Top four qualify. The playoff champion goes up; only last place goes down. A tied match uses sudden aperture. Five healthy configured starters or bench substitutes are required.'],['Generations matter','New applicants arrive every year. Wizards retire around 60 and may teach until natural death around 85. The original staff may be inherited by several generations. Archives retain each career; Hall of Fame induction grants one-time Prestige.'],['Time, safety, and saves','Up to twelve hours of absence progress on return. Beyond that, the academy calendar pauses too. New-floor combat pauses when hidden and resumes when visible. Local saves use IndexedDB; cloud saves use revision-checked transactions. There is no shared player marketplace or anti-cheat server.'],['Coping with catastrophe','Applicants remain for three years. Recruitment is free. If the academy is empty, time still brings another applicant pool. Equipment can be recovered through a paid service or by clearing its loss floor. No gold is needed to recruit.'],['Reading an item roll','Typical rolls cluster near their expected value, but exceptional and anomalous outliers are possible at any rarity. The quality label describes the power roll. HP, mana, and defense roll independently. Compare actual statistics; rarity alone is not enough.']].map(([h,p])=>`<div class="card"><h3>${h}</h3><p style="margin-top:10px">${p}</p></div>`).join('')}</div>`;}
function inventoryContent(){let rows=s.items.filter(i=>(!inventory.family||i.family===inventory.family)&&(inventory.rarity===''||i.rarity===Number(inventory.rarity))&&(!inventory.slot||i.slot===inventory.slot)&&(!inventory.owner||(inventory.owner==='equipped'?i.owner:!i.owner))&&(!inventory.search||i.name.toLowerCase().includes(inventory.search.toLowerCase())));rows.sort((a,b)=>inventory.sort==='name'?a.name.localeCompare(b.name):b[inventory.sort]-a[inventory.sort]);const total=rows.length;rows=rows.slice(inventory.page*20,inventory.page*20+20);return `<p class="panel-intro">Equipment is found below the academy. Its spells define the wizard. Every roll is unique; lower rarities can still be extraordinary. Above 180 active items, unequipped items are safely shelved in Deep Storage.</p><div class="filters"><label>Family<select data-change="inventory" data-key="family">${options([['','All families'],...FAMILIES.map(f=>[f.id,f.name])],inventory.family)}</select></label><label>Rarity<select data-change="inventory" data-key="rarity">${options([['','All rarities'],...RARITIES.map((r,i)=>[i,r])],inventory.rarity)}</select></label><label>Slot<select data-change="inventory" data-key="slot">${options([['','All slots'],['focus','Focus'],['robe','Robe'],['charm','Charm']],inventory.slot)}</select></label><label>Status<select data-change="inventory" data-key="owner">${options([['','All items'],['equipped','Equipped'],['free','Unequipped']],inventory.owner)}</select></label><label>Sort<select data-change="inventory" data-key="sort">${options([['power','Power'],['hp','HP'],['mana','Mana'],['defense','Defense'],['rarity','Rarity'],['floor','Depth'],['name','Name']],inventory.sort)}</select></label><label>Search<input id="item-search" value="${esc(inventory.search)}" placeholder="Item name"></label></div><div class="cards">${rows.map(i=>itemCard(i)).join('')||empty('No equipment matches. Most equipment comes from dungeon discoveries, especially bosses.')}</div><div class="pagination">${inventory.page?button('Previous','item-page','data-dir="-1"','secondary'):''}<span class="fineprint">${total} items · page ${inventory.page+1}</span>${(inventory.page+1)*20<total?button('Next','item-page','data-dir="1"','secondary'):''}</div>`;}
function itemCard(i){const f=family(i.family);return `<article class="card"><div class="card-header"><span class="item-glyph" style="color:${f.color};text-shadow:0 1px 1px #0005">${f.icon}</span><div><h3>${esc(i.name)} ${i.locked?'♢':''}</h3><span class="tag rarity" style="background:${RARITY_COLORS[i.rarity]}55">${RARITIES[i.rarity]}</span>${tag(i.slot)}${tag('Floor '+i.floor)}</div></div><span class="item-power">${fmt(i.power)}</span> <small>power · ${i.quality}</small><p>+${i.hp} HP · +${i.mana} mana · +${i.defense} defense</p><p>${f.spell} · Tier ${i.tier} · ${i.charges} charges/cast</p>${i.owner?`<small>Carried by ${esc(s.wizards.find(w=>w.id===i.owner)?.name||'an archived wizard')}</small>`:''}<div class="actions">${button('Inspect & compare','item',`data-id="${i.id}"`,'secondary')}</div></article>`;}
function suppliesContent(shop=true){return `<div class="metrics">${metric('Unscribed runes',n(s.blanks))}${metric('Seal ingredients',n(s.ingredients))}${metric('Boss Seals',n(s.seals))}${metric('Potions',n(s.potions))}</div><div class="table-wrap"><table><thead><tr><th>Rune charges</th><th>Tier I</th><th>Tier II</th><th>Tier III</th></tr></thead><tbody>${FAMILIES.map(f=>`<tr><td>${f.icon} ${f.name}</td><td>${n(s.runes[f.id])}</td><td>${n(s.runes[f.id+'2'])}</td><td>${n(s.runes[f.id+'3'])}</td></tr>`).join('')}</tbody></table></div>${shop?`${section('The supply counter')}<p class="panel-intro">Equipment is never sold here. Emergency consumables keep an expedition supplied.</p><div class="actions">${button('5 potions · 100 gold','buy','data-kind="potions"','secondary')}${button('20 blank runes · 100 gold','buy','data-kind="blanks"','secondary')}${button('Bind 1 seal · 3 ingredients + 15 gold','bind-seal','','secondary')}</div>`:''}`;}
function renderItem(){const i=route.item||s.items.find(i=>i.id===route.id);if(!i){panel('Missing item','Strongroom',empty('That item is not in active storage. Check Deep Storage or lost caches.'));return;}const f=family(i.family);let html=itemCard(i);html+=section('Granted magic')+`<p>${esc(f.spell)} · ${f.kind==='heal'?'Heals the most injured ally and cleanses poison and curse.':f.kind==='shield'?'Shields the most vulnerable ally and draws enemy attacks.':f.kind==='summon'?'Raises a fighting custodian that absorbs attacks.':f.kind==='aoe'?'Hits every enemy and applies '+f.status+'.':'Strikes an enemy and applies '+f.status+'.'}</p><div class="note">Consumes ${i.charges} ${f.name} tier ${i.tier} rune charges per cast. Mana persists between floors. This item has an uncapped probability-distributed power roll of ${i.roll.toFixed(3)}× its rarity and depth baseline.</div>${i.affixes.map(a=>`<p class="affix"><strong>${AFFIXES.find(x=>x.id===a)?.name}</strong> · ${AFFIXES.find(x=>x.id===a)?.desc}</p>`).join('')}`;
 const available=s.items.some(x=>x.id===i.id);if(available){html+=section('Compare & equip')+`<label>Wizard<select id="equip-target">${options([['','Choose a wizard'],...M.active(s).map(w=>[w.id,w.name])],route.target||i.owner||'')}</select></label><div id="item-comparison">${comparison(i,route.target||i.owner)}</div><div class="actions" style="margin-top:15px">${button('Equip to selected wizard','equip-item',`data-id="${i.id}"`)}${button(i.locked?'Unlock item':'Lock item','lock-item',`data-id="${i.id}"`,'secondary')}${!i.owner?button('Shelve safely','vault-item',`data-id="${i.id}"`,'secondary'):''}${!i.locked&&!i.owner?button('Sell · '+n(i.value)+' gold','sell-item',`data-id="${i.id}"`,'danger'):''}</div>`;}html+=section('Provenance')+`<p class="fineprint">Found in year ${i.found.year} · Floor ${i.found.floor}${i.found.boss?' · '+esc(i.found.boss):''}<br>Discovered by ${esc(i.found.wizard)}<br>Original rarity: ${RARITIES[i.rarity]} · ${esc(i.id)}</p><div class="chips">${i.owners.map(o=>tag(o.name+' · Y'+o.year)).join('')||tag('No previous owners')}</div>`;panel(i.name,'Equipment · '+f.name,html);}
function comparison(i,id){const w=s.wizards.find(w=>w.id===id);if(!w)return '';const old=s.items.find(x=>x.id===w.equipment[i.slot]);return `<div class="note">${old?'Replacing '+esc(old.name):'Empty '+i.slot+' slot'}<div class="metrics">${['power','hp','mana','defense'].map(k=>metric(k,`${i[k]-(old?.[k]||0)>=0?'+':''}${fmt(i[k]-(old?.[k]||0))}`)).join('')}</div></div>`;}
function renderWizard(){const w=s.wizards.find(w=>w.id===route.id)||s.applicants.find(w=>w.id===route.id)||historyWizard;if(!w){panel('Wizard archive','Career',empty('Record not found.'));return;}const a=M.attributes(s,w),current=s.wizards.includes(w),applicant=s.applicants.includes(w),onExp=s.expedition?.ids.includes(w.id),canEdit=current&&w.status==='Active';let html=`<div class="card-header">${portrait(w)}<div><h3>${esc(w.name)}</h3><p>${esc(w.status)} · Age ${w.departure?.age||M.age(s,w)} · ${w.founder?'Founding wizard · ':''}${TRAITS[w.trait][0]}</p></div></div><p class="panel-intro">${TRAITS[w.trait][1]} · Joined in year ${Math.floor(w.joined/DAY)+1}${w.departure?' · '+esc(w.departure.cause)+', year '+w.departure.year:''}</p><div class="metrics">${metric('Level',w.level)}${metric('HP',Math.round(w.hp||0)+' / '+a.hp)}${metric('Mana',Math.round(w.mana||0)+' / '+a.mana)}${metric('Power',a.power)}</div><div class="bar"><i style="width:${Math.min(100,w.xp/(100*w.level**1.3)*100)}%"></i></div><p class="fineprint">${n(w.xp)} / ${n(100*w.level**1.3)} adventure XP · Magic Missile is always available.</p>`;
 if(s.rooms.hall&&qualifies(w)&&!w.hof&&!applicant)html+=`<div class="note">This career qualifies for the Hall of Names. ${button('Induct into the Hall','induct',`data-id="${w.id}"`)}</div>`;
 if(canEdit)html+=taskMarkup(w);
 if(canEdit)html+=`${section('Work & expedition behavior')}<div class="split"><label>Assignment<select data-change="job" data-id="${w.id}" ${onExp?'disabled':''}>${options(Object.entries(JOBS),w.job)}</select></label><label>Position<select data-change="position" data-id="${w.id}" ${onExp?'disabled':''}>${options(['Front','Middle','Back'].map(x=>[x,x]),w.position)}</select></label><label>Directive<select data-change="directive" data-id="${w.id}" ${onExp?'disabled':''}>${options(['Aggressive','Balanced','Conservative','Support'].map(x=>[x,x]),w.directive)}</select></label></div><p class="fineprint" style="margin-top:10px">Aggressive casts faster. Conservative saves half its mana for emergencies. Support prioritizes help over damage.</p><div class="actions" style="margin-top:15px">${button('Use restorative potion','potion',`data-id="${w.id}" ${onExp&&s.combat?.state==='fighting'?'disabled':''}`,'secondary')}${button('Retire from active service','retire',`data-id="${w.id}" ${onExp||M.age(s,w)<50?'disabled':''}`,'secondary')}</div>`;
 html+=section('Equipment')+`<div class="cards">${Object.entries(w.equipment).map(([slot,id])=>{const it=s.items.find(i=>i.id===id);return `<div class="card"><p class="subheading">${slot.toUpperCase()}</p><h3>${it?esc(it.name):id?'Archived equipment':'Unadorned'}</h3><p>${it?family(it.family).spell:'Magic Missile requires no special equipment.'}</p>${it?`<div class="actions">${button('Inspect','item',`data-id="${it.id}"`,'secondary')}${canEdit?button('Unequip','unequip',`data-id="${w.id}" data-slot="${slot}" ${onExp?'disabled':''}`,'secondary'):''}</div>`:''}</div>`;}).join('')}</div>`;
 html+=section('Arcane Rift identity')+`<div class="metrics">${metric('Sport level',w.sportLevel)}${metric('Potential',w.potential)}${metric('Appearances',n(w.stats.appearances))}${metric('Goals',n(w.stats.goals))}</div><div class="stat-grid">${Object.entries(w.sport).map(([k,v])=>`<div class="stat-cell">${k}<b>${fmt(v+(w.sportLevel-1)*(1+w.potential/100))}</b></div>`).join('')}</div><p class="fineprint" style="margin-top:10px">Rift XP ${n(w.sportXP)} / ${n(100*w.sportLevel**1.3)} · Equipment family, potential, age, and position affect match rating.</p>${section('People who matter')}<div class="chips">${Object.values(w.relationships||{}).map(r=>tag(r.name+' · '+r.kind+' ('+r.value+')')).join('')||'<small>New relationships are still waiting to happen.</small>'}</div>${(w.notes||[]).map(x=>`<p class="fineprint">${esc(x)}</p>`).join('')}${section('The complete career')}<div class="stat-grid">${Object.entries(STATS).map(([k,label])=>`<div class="stat-cell">${label}<b>${fmt(w.stats[k])}</b></div>`).join('')}</div>${applicant?`<div class="actions" style="margin-top:20px">${button('Offer a place','recruit',`data-id="${w.id}"`)}</div>`:''}`;panel(w.name,'Every wizard has a story',html);}
function gateContent(){const ws=M.active(s).filter(w=>!w.injury);return `<p class="panel-intro">A party of up to three. Automatic combat. Permanent consequences. Front positions draw more attacks. Prepare at the academy, then decide when to come home.</p>${s.expedition?`<div class="note">Party currently on floor ${s.expedition.floor}. ${button('Return to expedition','combat')}</div>`:''}<div class="metrics">${metric('Deepest floor',s.depth)}${metric('Boss Seals',s.seals)}${metric('Potions',s.potions)}${metric('Lost caches',s.lost.length)}</div>${section('Expedition roster')}<div class="cards">${ws.map(w=>`<div class="card"><div class="card-header">${portrait(w)}<div><h3>${esc(w.name)}</h3><p>Level ${w.level} · ${w.position} · ${w.directive}</p></div></div><p>${Math.round(w.hp)} HP / ${M.attributes(s,w).hp} · ${Math.round(w.mana)} mana</p><div class="actions">${button(s.party.includes(w.id)?'✓ In party':'Add to party','party',`data-id="${w.id}" ${s.expedition?'disabled':''}`,s.party.includes(w.id)?'':'secondary')}${button('Prepare','wizard',`data-id="${w.id}"`,'secondary')}</div></div>`).join('')||empty('Recruit healthy wizards before opening the gate.')}</div><div class="note warning">Wizards who fall die permanently. Their equipment remains at the loss floor. With no runes, everyone still has Magic Missile.</div><div class="actions">${button('Enter floor '+(s.depth+1),'expedition',`data-floor="${s.depth+1}" ${s.expedition||!s.party.length?'disabled':''}`)}${button('Inspect next boss','boss-info','','secondary')}</div>${section('Return to cleared territory')}<div class="split"><label>Cleared floor<input id="revisit-floor" type="number" min="1" max="${Math.max(1,s.depth)}" value="${Math.max(1,s.depth)}"></label><div class="actions">${button('Enter selected floor','revisit',`${!s.depth||s.expedition?'disabled':''}`,'secondary')}</div></div>${section('Automated patrols')}<p class="panel-intro">One patrol every five minutes. The first three available assigned wizards fight together. Only cleared floors. Real combat, real loot, real deaths. Patrols pause while a manual expedition is outside.</p><div class="split"><label>Normal patrol floor<input data-change="farm-floor" type="number" min="1" max="${Math.max(1,s.depth)}" value="${s.farmFloor}"></label><label>Boss patrol floor<input data-change="boss-floor" type="number" min="10" step="10" max="${Math.max(10,Math.floor(s.depth/10)*10)}" value="${s.bossFloor}"></label></div>${assignmentPanel(['farm','boss'])}${section('Lost equipment')}<div class="cards">${s.lost.map(c=>`<div class="card"><h3>Floor ${c.floor} · Year ${c.year}</h3><p>${esc(c.names.join(', '))}</p><p>${c.items.length} items · ${esc(c.items.map(i=>i.name).join(', '))}</p>${c.ready?`<div class="note">Retrieval party returns in ${duration(c.ready-s.time)}.</div>`:`<div class="actions">${button('Hire retrieval · '+n(c.cost)+' gold','retrieve',`data-id="${c.id}"`,'secondary')}${button('Recover with this party','expedition',`data-floor="${c.floor}" ${s.expedition||!s.party.length?'disabled':''}`,'secondary')}</div>`}</div>`).join('')||empty('Nothing left behind. Keep it that way.')}</div>`;}
function renderCombat(){const c=s.combat;if(!c){panel('Belowstairs','Expedition',empty('There is no expedition to watch.'));return;}const unit=(h,hero=false)=>{const w=s.wizards.find(w=>w.id===h.id);return `<div data-unit="${h.id}" class="combatant ${h.hp<=0?'dead':''}">${hero&&w?portrait(w):'<div class="enemy-icon">'+(c.boss?'♜':'◈')+'</div>'}<strong>${esc(h.name)}</strong><div class="bar"><i style="width:${Math.max(0,h.hp/h.maxHP*100)}%"></i></div><small>${Math.ceil(h.hp)} / ${Math.ceil(h.maxHP)} HP</small>${hero?`<div class="bar mana"><i style="width:${h.mana/h.maxMana*100}%"></i></div><small>${Math.floor(h.mana)} mana · ${h.position}</small>`:''}<div class="status-chips">${Object.keys(h.status).join(' · ')}${h.barrier>0?' ⬡ '+Math.round(h.barrier):''}</div></div>`;};let html=`<div class="combat-arena arena-theatre" data-encounter="${c.id}" data-state="${c.state}" data-units="${[...c.enemies,...c.heroes].map(h=>h.id).join(',')}"><div class="arena-ribbon"><span>FLOOR ${c.floor}</span><strong>${arenaTheme(c.floor).name}</strong><span class="arena-kind">${c.boss?'BOSS':c.kind.toUpperCase()}</span></div><canvas id="combat-canvas" role="img" aria-label="Animated dungeon arena showing your wizards, enemies, spells, and summons. Exact combat statistics and results are available below."></canvas><div class="arena-footer"><span class="battle-between">${c.boss?'BOSS · PHASE '+c.phase:'Formation: front · middle · back'}</span><span class="summon-strip">${c.summons.filter(x=>x.hp>0).length} summons</span></div></div><p class="arena-caption">Live spells · Damage on impact · Green + healing · Blue ⬡ absorbed damage</p><details class="arena-roster"><summary>Party & enemy condition</summary><div class="battle-row">${c.heroes.map(h=>unit(h,true)).join('')}</div><div class="battle-row enemy-roster">${c.enemies.map(h=>unit(h)).join('')}</div></details>`;
 if(c.state==='choice'){const title=c.kind==='shrine'?'A shrine still listening':c.kind==='treasure'?'Two chests, one sensible decision':'A room the maps refuse to show';html+=`<div class="result-banner"><h3>${title}</h3><p>${c.kind==='shrine'?'Rest for free, or offer 30 gold for a barrier and confront the chamber’s guardians.':c.kind==='treasure'?'Take the modest chest safely, or face a mimic for a guaranteed item.':'Walk past safely, or spend 8 mana per wizard and fight for a guaranteed discovery.'}</p></div><div class="duo-actions">${button(c.kind==='shrine'?'Rest at the shrine':'Take the safe path','room-choice',`data-choice="${c.kind==='shrine'?'rest':'safe'}"`)}${button(c.kind==='shrine'?'Offer 30 gold & fight':'Investigate & fight','room-choice','data-choice="risk"','secondary')}</div>`;}
 else if(c.state==='fighting'){html+=`<div class="actions" style="margin:16px 0">${COMBAT_SPEEDS.map(speed=>button(({0.5:'Relaxed',1:'Normal',2:'Fast'})[speed],'combat-speed',`data-speed="${speed}"`,c.speed===speed?'':'secondary')).join('')}${button('Retreat to the academy','retreat','','danger')}<small data-combat-clock>${c.time.toFixed(0)} combat seconds</small></div>`;}
 else if(c.state==='victory'){html+=`<div class="result-banner"><h3>Floor secured. How greedy are we?</h3><p>+${n(c.reward?.gold)} gold${c.reward?.item?' · '+esc(c.reward.item):''}</p></div>${s.expedition?`<div class="duo-actions">${button('Advance to floor '+(c.floor+1),'advance',`${c.floor+1>s.depth+1?'disabled':''}`)}${button('Return to academy','return-home','','secondary')}</div><div class="actions" style="margin-top:12px">${c.heroes.filter(h=>h.hp>0).map(h=>button('Potion · '+esc(h.name.split(' ')[0]),'potion',`data-id="${h.id}"`,'secondary')).join('')}</div>`:button('Back to the gate','room','data-room="gate"','secondary')}`;}
 else html+=`<div class="result-banner defeat"><h3>${c.state==='defeat'?'They did not return.':'Expedition withdrawn.'}</h3><p>${c.state==='defeat'?'Their names remain. Their equipment waits below.':'Prepare again at the academy.'}</p></div>${button('Back to Belowstairs','room','data-room="gate"','secondary')}`;
 html+=section('Combat ledger')+`<div class="combat-log">${c.log.slice(-30).map(x=>`<div><time>${x.t}s</time>${esc(x.text)}</div>`).join('')}</div>`;panel('Floor '+c.floor+' · '+(c.boss?C.bossFor(c.floor).name:'Belowstairs'),'The living dungeon · automatic real-time combat',html);}
function updateCombatView(){
 const c=s.combat,body=$('panel-body'),arena=body.querySelector('.combat-arena');
 const signature=[...c.enemies,...c.heroes].map(h=>h.id).join(',');
 if(!arena||arena.dataset.encounter!==c.id||arena.dataset.state!==c.state||arena.dataset.units!==signature){
  const scroll=body.scrollTop;renderCombat();body.scrollTop=scroll;return;
 }
 for(const el of body.querySelectorAll('[data-unit]')){
  const h=[...c.enemies,...c.heroes].find(h=>h.id===el.dataset.unit);if(!h)continue;
  el.classList.toggle('dead',h.hp<=0);
  const bars=el.querySelectorAll('.bar i'),labels=el.querySelectorAll('small');
  bars[0].style.width=Math.max(0,h.hp/h.maxHP*100)+'%';
  labels[0].textContent=Math.ceil(h.hp)+' / '+Math.ceil(h.maxHP)+' HP';
  if(bars[1]){bars[1].style.width=Math.max(0,h.mana/h.maxMana*100)+'%';labels[1].textContent=Math.floor(h.mana)+' mana · '+h.position;}
  el.querySelector('.status-chips').textContent=Object.keys(h.status).join(' · ')+(h.barrier>0?' ⬡ '+Math.round(h.barrier):'');
 }
 arena.querySelector('.battle-between').textContent='FLOOR '+c.floor+' · '+(c.boss?'BOSS · PHASE '+c.phase:c.kind.toUpperCase());
 arena.querySelector('.summon-strip').textContent=c.summons.filter(x=>x.hp>0).map(x=>x.name+' '+Math.ceil(x.hp)+' HP').join(' · ');
 const clock=body.querySelector('[data-combat-clock]');if(clock)clock.textContent=c.time.toFixed(0)+' combat seconds';
 const ledger=body.querySelector('.combat-log'),key=JSON.stringify(c.log.slice(-1));
 if(ledger&&ledger.dataset.lastEntry!==key){
  const atBottom=ledger.scrollHeight-ledger.scrollTop-ledger.clientHeight<30;
  ledger.innerHTML=c.log.slice(-30).map(x=>`<div><time>${x.t}s</time>${esc(x.text)}</div>`).join('');
  ledger.dataset.lastEntry=key;if(atBottom)ledger.scrollTop=ledger.scrollHeight;
 }
}
function riftContent(){const tab=route.tab;let html=tabs([['league','League'],['lineup','Lineup & tactics'],['watch','Match theatre'],['schools','Rivals'],['playoffs','Playoffs'],['records','Records']],tab);const team=L.playerSchool(s);if(tab==='league'){html+=`<div class="metrics">${metric('Season',s.league.year)}${metric('Games played',Math.min(14,s.league.round))}${metric('Your league',LEAGUES[team.league].replace(' League',''))}${metric('Championships',team.titles)}</div><div class="tabs">${LEAGUES.map((l,i)=>button(l,'league',`data-league="${i}"`,leagueView===i?'active':'')).join('')}</div>${standingsTable(L.standings(s,leagueView))}<div class="note">Top four reach the playoffs. The playoff champion is promoted. Only last place is relegated. Every academy plays fourteen regular-season games.</div><p class="fineprint">Next fixture: ${esc(L.nextFixture(s).label)} · in ${duration(L.nextFixture(s).at-s.time)}. Rounds resolve automatically as time passes.</p>`;}
 else if(tab==='lineup'){const ws=M.active(s);html+=`<p class="panel-intro">Select five distinct starters. Injured or dungeon-bound wizards are replaced by available configured bench players. An incomplete team forfeits. Normal academy jobs do not prevent sport participation.</p>${['Striker I','Striker II','Controller','Warden I','Warden II'].map((p,i)=>`<div class="selector-row"><strong>${p}</strong><select data-change="lineup" data-index="${i}">${options([['','Unfilled position'],...ws.map(w=>[w.id,`${w.name} · ${L.rating(s,w,i)} rating${w.injury?' · injured':''}`])],s.lineup[i]||'')}</select></div>`).join('')}${section('The bench')}${[0,1,2].map(i=>`<div class="selector-row"><strong>Reserve ${i+1}</strong><select data-change="bench" data-index="${i}">${options([['','No reserve'],...ws.map(w=>[w.id,w.name])],s.bench[i]||'')}</select></div>`).join('')}${section('Match tactics')}<div class="split">${Object.entries({tempo:['Slow','Balanced','Fast'],focus:['Offensive','Balanced','Defensive'],passing:['Safe','Balanced','Risky']}).map(([k,vs])=>`<label>${k[0].toUpperCase()+k.slice(1)}<select data-change="tactics" data-key="${k}">${options(vs.map(v=>[v,v]),s.tactics[k])}</select></label>`).join('')}</div><div class="note">Fast tempo adds possessions. Offensive focus improves scoring at a defensive cost. Risky passing can produce two-point goals, but is intercepted more often.</div>${facultyPanel('rift')}${facilityHeader('rift')}`;}
 else if(tab==='watch'){const m=s.league.lastMatch;html+=m?`<div class="scoreboard"><h3>${esc(m.aName)}</h3><strong>${m.score[0]} – ${m.score[1]}</strong><h3>${esc(m.bName)}</h3></div><p class="panel-intro">Year ${m.year} · ${m.stage} · ${esc(m.quote||'')}</p>${button('Watch the match replay','watch-last')}${section('This season’s fixtures')}<div class="table-wrap"><table><thead><tr><th>Opponent</th><th>Score</th><th>Stage</th><th>Replay</th></tr></thead><tbody>${s.league.matches.filter(m=>m.a==='player'||m.b==='player').map(m=>`<tr><td>${esc(s.league.schools.find(t=>t.id===(m.a==='player'?m.b:m.a)).name)}</td><td>${m.score.join(' – ')}</td><td>${m.stage}</td><td>${button('Watch','load-match',`data-id="${m.id}"`,'secondary small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Your first match is scheduled. Set a lineup before the bell. Replays preserve every play; watching does not award duplicate rewards.');}
 else if(tab==='records'){html+=`<p class="panel-intro">The leading fifty careers across all 32 academies. Retired athletes retain their place until a later generation surpasses them.</p><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Wizard</th><th>Academy</th><th>Career points</th></tr></thead><tbody>${(s.league.records?.goals||[]).map((r,i)=>`<tr class="${r.team==='player'?'you':''}"><td>${i+1}</td><td>${esc(r.name)}</td><td>${esc(s.league.schools.find(t=>t.id===r.team)?.name||r.team)}</td><td>${n(r.value)}</td></tr>`).join('')}</tbody></table></div>${section('Current season leaders')}<div class="table-wrap"><table><thead><tr><th>Wizard</th><th>Points</th><th>Assists</th><th>Stops</th><th>Steals</th></tr></thead><tbody>${Object.values(s.league.seasonPlayers).sort((a,b)=>b.goals-a.goals).slice(0,30).map(r=>`<tr><td>${esc(r.name)}</td><td>${r.goals}</td><td>${r.assists}</td><td>${r.blocks}</td><td>${r.steals}</td></tr>`).join('')}</tbody></table></div>`;}
 else if(tab==='schools')html+=`<div class="cards">${s.league.schools.filter(t=>t.id!=='player').map(t=>{const h=s.league.headToHead[t.id];const star=t.roster.slice().sort((a,b)=>(b.stats.goals||0)-(a.stats.goals||0))[0];return `<div class="card"><h3>${esc(t.name)}</h3><p>${LEAGUES[t.league]} · ${t.titles} titles · ${esc(t.personality)}</p><div class="note">“${esc(t.quote)}”</div><p>Star: ${esc(star?.name||'An open roster')} · ${n(star?.stats.goals)} career points</p><p>All-time ${t.career.wins}–${t.career.losses}. ${h?'Against you: '+h.losses+' wins, '+h.wins+' losses.':'No head-to-head history yet.'}</p><details><summary style="padding:13px 0;cursor:pointer">Current roster</summary>${t.roster.map(w=>`<div class="list-row"><strong>${esc(w.name)}</strong><small>Age ${M.age(s,w)} · Lv ${w.sportLevel} · ${n(w.stats.goals)} pts</small></div>`).join('')}</details></div>`;}).join('')}</div>`;
 else html+=`<div class="cards">${LEAGUES.map((name,i)=>{const p=s.league.playoffs[i],school=id=>esc(s.league.schools.find(t=>t.id===id)?.name||'');return `<div class="card"><h3>${name}</h3>${p?`<p>Regular-season winner: ${school(p.regularChampion)}</p><div class="note">Semifinal: ${school(p.seeds[0])} vs ${school(p.seeds[3])}<br>Semifinal: ${school(p.seeds[1])} vs ${school(p.seeds[2])}</div><p>Final: ${p.finalists.map(school).join(' vs ')}</p><h3>${p.champion?'Champion: '+school(p.champion):'Final pending'}</h3>`:'<p>The top four qualify after fourteen regular-season rounds.</p>'}</div>`;}).join('')}</div>`;return html;}
function standingsTable(rows){return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Academy</th><th>W</th><th>L</th><th>For</th><th>Against</th><th>+/−</th></tr></thead><tbody>${rows.map((t,i)=>`<tr class="${t.id==='player'?'you':''}"><td>${i+1}${i<4?' ◇':''}</td><td>${esc(t.name)}</td><td>${t.w}</td><td>${t.l}</td><td>${t.pf}</td><td>${t.pa}</td><td>${t.pf-t.pa}</td></tr>`).join('')}</tbody></table></div>`;}
function recordsContent(){const {metric:key,status}=recordFilters;let rows=status==='All-Time'?(s.records[key]||[]):s.wizards.filter(w=>status==='Living'?w.status!=='Deceased':status==='Hall of Fame'?w.hof:w.status===status).map(w=>({id:w.id,name:w.name,value:w.stats[key]||0,status:w.status}));if(status==='Current Year')rows=s.wizards.map(w=>({id:w.id,name:w.name,value:w.yearStats?.[key]||0,status:w.status}));if(status==='Deceased')rows=(s.records[key]||[]).filter(w=>w.status==='Deceased');rows.sort((a,b)=>b.value-a.value);return `<p class="panel-intro">All-time boards retain the leading 25 careers for every category. Every other career remains in the paginated Wizard Archives. Academy totals count all generations.</p><div class="filters"><label>Category<select data-change="record" data-key="metric">${options(Object.entries(STATS),key)}</select></label><label>People<select data-change="record" data-key="status">${options(['All-Time','Current Year','Living','Retired','Faculty','Deceased','Hall of Fame'].map(x=>[x,x]),status)}</select></label></div><div class="metrics">${metric('Academy total',fmt(s.stats[key]))}${metric('Record',fmt(rows[0]?.value))}${metric('Careers begun',n(s.stats.recruited))}${metric('Years',M.year(s))}</div><div class="table-wrap"><table><thead><tr><th>#</th><th>Wizard</th><th>${STATS[key]}</th><th>Status</th><th>Career</th></tr></thead><tbody>${rows.slice(0,25).map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.name)}</td><td>${fmt(r.value)}</td><td>${r.status}</td><td>${button('Read','history-wizard',`data-id="${r.id}"`,'secondary small')}</td></tr>`).join('')}</tbody></table></div>`;}
function eventContent(){return `<p class="panel-intro">The academy presents one or two meaningful decisions each year. Unanswered decisions remain here; routine overflow is handled by the office.</p><div class="cards">${s.events.map(e=>`<article class="card"><p class="eyebrow" style="color:#9b8150">YEAR ${e.year} · OFFICE MATTER</p><h3 style="margin:10px 0">${esc(e.title)}</h3><p>${esc(e.body)}</p><div class="actions" style="display:grid">${e.choices.map((c,i)=>button(esc(c.label)+(c.cost?' · '+c.cost+' gold':''),'event-choice',`data-id="${e.id}" data-index="${i}" ${s.gold<c.cost?'disabled':''}`,i?'secondary':'')).join('')}</div></article>`).join('')||empty('No outstanding decisions. An astonishing administrative achievement.')}</div>`;}
function renderEvents(){panel('Matters requiring a Headmaster','The noticeboard',eventContent());}
function showReport(r){route={type:'report'};panel('While you were away','The academy kept going',`<p class="panel-intro">${duration(r.elapsed)} of academy life${r.capped?' · Twelve-hour idle limit reached. Additional absence paused the academy calendar.':''}.</p><div class="metrics">${metric('Gold change',(r.gold>=0?'+':'')+n(r.gold))}${metric('Blank runes',(r.blanks>=0?'+':'')+n(r.blanks))}${metric('Rune charges',(r.runes>=0?'+':'')+n(r.runes))}${metric('Levels gained',Math.max(0,r.levels))}${metric('Boss seals',(r.seals>=0?'+':'')+r.seals)}${metric('Potions',(r.potions>=0?'+':'')+r.potions)}</div>${section('The important parts')}${r.events.map(e=>`<div class="history-entry"><small>YEAR ${e.year} · ${esc(e.kind)}</small>${esc(e.text)}</div>`).join('')||'<p class="muted">Training continued. The corridors remained largely intact.</p>'}<div class="note">Unknown dungeon floors never advance offline. Any live manual encounter waits for you.</div>${button('Back to the academy','close')}`);}
async function loadHistory(type,reset=false){const epoch=modalEpoch;if(reset){archiveCursor='';archivePage=null;}archiveType=type;try{await P.saveLocal(s);const result=await P.listArchive(type,archiveCursor,30);if(epoch!==modalEpoch||!$('archive-list'))return;archivePage=result;const rows=result.rows;let html=rows.map(({id,data:w})=>{if(type==='wizards'||type==='honors')return `<div class="list-row">${type==='honors'?portrait(w):''}<div class="name"><strong>${esc(w.name)}</strong><br><small>${esc(w.status)} · Level ${w.level} · ${w.hof?'Hall of Fame · ':''}Year ${Math.floor(w.joined/DAY)+1}</small></div>${button('Read career','history-wizard',`data-id="${id}"`,'secondary')}</div>`;if(type==='items')return `<div class="list-row"><div class="name"><strong>${esc(w.name)}</strong><br><small>${RARITIES[w.rarity]} · ${w.quality} · ${fmt(w.power)} power · ${w.sold?'Sold':w.vault?'Shelved':w.lostFloor?'Lost on floor '+w.lostFloor:'In circulation'}</small></div>${w.vault&&!s.items.some(i=>i.id===id)?button('Withdraw','withdraw',`data-id="${id}"`,'secondary'):button('Provenance','item-history',`data-id="${id}"`,'secondary')}</div>`;return `<div class="history-entry"><small>YEAR ${w.year||Math.floor(w.time/DAY)+1}${w.name?' · '+esc(w.name):''}</small>${esc(w.text||w.body||w.title||'')}</div>`;}).join('')||empty('No records in this section yet.');html+=`<div class="pagination">${archiveCursor?button('Start of archive','archive-first','','secondary'):''}${result.next?button('Next 30 records','archive-next','','secondary'):''}</div>`;$('archive-list').innerHTML=html;}catch(e){if($('archive-list'))$('archive-list').innerHTML=empty(esc(errorMessage(e)));}}
function renderMatch(){const m=route.match;if(!m)return;const idx=watch.id===m.id?watch.index:0,play=m.plays[Math.min(idx,m.plays.length-1)],score=play?.score||[0,0];let html=`<div class="scoreboard"><h3>${esc(m.aName)}<small>${m.stage}</small></h3><strong>${score[0]} – ${score[1]}</strong><h3>${esc(m.bName)}<small>Year ${m.year}</small></h3></div><div class="rift-pitch"><div class="aperture"></div><div class="aperture"></div>${Array.from({length:10},(_,i)=>`<span class="rift-player ${i>=5?'away':''}" style="left:${(i<5?15:57)+(i%3)*8+Math.sin(idx+i)*3}%;top:${22+(i%5)*13+Math.cos(idx+i)*4}%"></span>`).join('')}<span class="mote" style="left:${play?.side===0?65+Math.sin(idx)*15:35+Math.sin(idx)*15}%;top:${50+Math.cos(idx)*18}%"></span></div><div class="note" style="min-height:74px">${esc(play?.text||'The aperture opens.')}</div><div class="actions">${button(watch.playing?'Pause':'Play replay','replay-toggle')}${button('Next play','replay-next','','secondary')}${button('Final score','replay-end','','secondary')}<small>Play ${Math.min(idx+1,m.plays.length)} / ${m.plays.length}</small></div><p class="fineprint" style="margin-top:14px">This is the recorded match. Replaying never changes outcomes or awards rewards again.</p>${section('The people behind the score')}<div class="table-wrap"><table><thead><tr><th>Wizard</th><th>Goals</th><th>Assists</th><th>Stops</th><th>Steals</th><th>Fouls</th></tr></thead><tbody>${m.players.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.goals}</td><td>${p.assists}</td><td>${p.blocks}</td><td>${p.steals}</td><td>${p.fouls}</td></tr>`).join('')}</tbody></table></div><div class="combat-log">${m.plays.slice(0,idx+1).map(p=>`<p>${esc(p.text)}</p>`).join('')}</div>`;panel('Arcane Rift','Match theatre · recorded play-by-play',html);}
function renderSeason(){const season=route.season;if(!season)return;const school=id=>s.league.schools.find(t=>t.id===id)?.name||id;panel('Year '+season.year,'A complete season, preserved',`<p class="panel-intro">${season.award?'Golden Mote: '+esc(season.award.name)+' · '+season.award.goals+' points':''}</p>${LEAGUES.map((name,i)=>{const rows=Object.values(season.tables).filter(t=>t.league===i).sort((a,b)=>b.w-a.w||(b.pf-b.pa)-(a.pf-a.pa)),p=season.playoffs[i];return `${section(name)}${standingsTable(rows)}<div class="note">Regular-season champion: ${esc(school(p.regularChampion))}<br>Final: ${p.finalists.map(id=>esc(school(id))).join(' vs ')}<br><strong>League champion: ${esc(school(p.champion))}</strong><br>${season.moves.filter(m=>m.from===i).map(m=>`${esc(school(m.id))} → ${LEAGUES[m.to]}`).join('<br>')}</div>`;}).join('')}${section('Individual season statistics')}<div class="table-wrap"><table><thead><tr><th>Wizard</th><th>Academy</th><th>Points</th><th>Assists</th><th>Stops</th><th>Appearances</th></tr></thead><tbody>${Object.values(season.players).sort((a,b)=>b.goals-a.goals).slice(0,50).map(w=>`<tr><td>${esc(w.name)}</td><td>${esc(school(w.team))}</td><td>${w.goals}</td><td>${w.assists}</td><td>${w.blocks}</td><td>${w.appearances}</td></tr>`).join('')}</tbody></table></div><p class="fineprint">Leading 50 players displayed. Full player statistics are preserved in the complete backup.</p>${section('Your fixtures')}<div class="cards">${season.matches.filter(m=>m.a==='player'||m.b==='player').map(m=>`<div class="card"><p>${esc(school(m.a))} ${m.score.join(' – ')} ${esc(school(m.b))}</p><div class="actions">${button('Watch archived match','load-match',`data-id="${m.id}"`,'secondary')}</div></div>`).join('')}</div>`);}
async function archived(type,id){return s.pending[`${type}/${id}`]?.data||await P.getArchive(type,id);}
function watchMatch(m){watch={id:m.id,index:0,playing:false,at:0};route={type:'match',match:m};renderPanel();}
function confirmPanel(title,text,action,data){route={type:'confirm'};panel(title,'Please review',`<div class="note warning">${text}</div><div class="actions">${button('Confirm',action,data,'danger')}${button('Cancel','close','','secondary')}</div>`);}
async function action(el){const a=el.dataset.act,id=el.dataset.id;if(a==='close'){$('panel').close();route=null;watch.playing=false;return;}if(a==='auth-toggle'){authMode=authMode==='signup'?'login':'signup';authScreen();return;}if(a==='local'){await enterAccount('local');return;}if(a==='reset-password'){const email=$('email').value;if(!email)throw Error('Enter your email address first.');await P.resetPassword(email);$('auth-status').textContent='Password reset requested. Check your inbox.';return;}
 if(!s)return;if(P.conflicted&&!['export','reload','logout','room','wizard','tab','save'].includes(a))throw Error('This session is paused because another device saved newer progress. Export a backup or reload from Settings.');
 if(a==='room'){openRoom(el.dataset.room,el.dataset.tab);return;}if(a==='tab'){route.tab=el.dataset.tab;archivePage=null;renderPanel();return;}if(a==='wizard'){historyWizard=null;route={type:'wizard',id};renderPanel();return;}if(a==='item'){route={type:'item',id};renderPanel();return;}if(a==='events'){route={type:'events'};renderPanel();return;}if(a==='combat'){route={type:'combat'};renderPanel();return;}if(a==='league'){leagueView=Number(el.dataset.league);renderPanel();return;}
 if(a==='open-foundation'){M.openFoundation(s);}
 else if(a==='recruit'){const w=M.recruit(s,id);if(!s.party.includes(w.id)&&s.party.length<3)s.party.push(w.id);const index=Array.from({length:5},(_,i)=>i).find(i=>!s.lineup[i]);if(index!==undefined)s.lineup[index]=w.id;toast(`${w.name} has a place at your academy.`);route={type:'room',id:'desk',tab:'applicants'};}
 else if(a==='upgrade'){M.upgrade(s,id);toast('The academy grows.');}
 else if(a==='party'){if(s.party.includes(id))s.party=s.party.filter(x=>x!==id);else if(s.party.length<3)s.party.push(id);else throw Error('A dungeon party has at most three wizards.');}
 else if(a==='expedition'||a==='revisit'){const floor=a==='revisit'?Number($('revisit-floor').value):Number(el.dataset.floor);if(!Number.isInteger(floor)||floor<1||floor>s.depth+(a==='revisit'?0:1))throw Error('Choose an accessible floor.');C.startExpedition(s,s.party,floor);route={type:'combat'};}
 else if(a==='advance'){if(s.combat?.state!=='victory'||!s.expedition)throw Error('Finish this floor first.');C.enterFloor(s,s.combat.floor+1);route={type:'combat'};}
 else if(a==='room-choice'){C.roomChoice(s,el.dataset.choice);}
 else if(a==='combat-speed'){if(s.combat&&COMBAT_SPEEDS.includes(Number(el.dataset.speed)))s.combat.speed=Number(el.dataset.speed);}
 else if(a==='retreat'||a==='return-home'){C.returnHome(s);route={type:'room',id:'gate',tab:'main'};}
 else if(a==='potion'){const w=s.wizards.find(w=>w.id===id);if(w)C.potion(s,w);}
 else if(a==='assign-recovery'){M.assign(s,s.wizards.find(w=>w.id===id),'recovery');}
 else if(a==='retrieve'){const cache=s.lost.find(c=>c.id===id);if(!cache||cache.ready)throw Error('That cache already has a retrieval order.');if(s.gold<cache.cost)throw Error('Not enough gold for the retrieval service.');s.gold-=cache.cost;cache.ready=s.time+Math.min(4*HOUR,300000+cache.floor*30000);M.news(s,`A retrieval service departs for floor ${cache.floor}.`,'recovery');}
 else if(a==='boss-info'){const floor=(Math.floor(s.depth/10)+1)*10,b=C.bossFor(floor);route={type:'boss-info'};panel(b.name,'Floor '+floor+' · One Boss Seal required',`<p class="panel-intro">${esc(b.desc)}</p><div class="note warning">${esc(b.hint)}</div><p>Every attempt consumes a seal, including the first. Resource-rich outcomes make up about 62% of boss clears. The remaining clears can reveal one of these signature items.</p>${section('Signature discoveries')}<div class="cards">${b.drops.map(d=>`<div class="card"><h3>${esc(d.name)}</h3><p>${family(d.family).name} · ${d.slot}</p></div>`).join('')}</div>`);return;}
 else if(a==='lock-item'){const it=s.items.find(i=>i.id===id);it.locked=!it.locked;M.archive(s,'items',it.id,it);}
 else if(a==='sell-item'){const it=s.items.find(i=>i.id===id);if(!it||it.locked||it.owner)throw Error('Only unlocked, unequipped items can be sold.');confirmPanel('Sell '+it.name+'?',`This permanently trades the item for ${n(it.value)} gold. Its provenance remains in the archives.`, 'confirm-sell',`data-id="${id}"`);return;}
 else if(a==='confirm-sell'){const it=s.items.find(i=>i.id===id);if(!it||it.locked||it.owner)throw Error('This item cannot be sold.');s.gold+=it.value;it.sold=true;M.archive(s,'items',id,it);s.items=s.items.filter(i=>i.id!==id);route={type:'room',id:'storage',tab:'items'};}
 else if(a==='vault-item'){const it=s.items.find(i=>i.id===id);if(it.owner)throw Error('Unequip this item first.');it.vault=true;M.archive(s,'items',id,it);s.items=s.items.filter(i=>i.id!==id);route={type:'room',id:'storage',tab:'items'};toast('Shelved safely. Find it in Deep Storage.');}
 else if(a==='withdraw'){const it=await archived('items',id);if(!it?.vault||it.sold||s.items.some(i=>i.id===id))throw Error('This item is not available in deep storage.');it.vault=false;s.items.push(it);M.archive(s,'items',id,it);route={type:'item',id};}
 else if(a==='equip-item'){const w=s.wizards.find(w=>w.id===$('equip-target').value);if(!w)throw Error('Choose a wizard first.');M.equip(s,w,id);route.target=w.id;toast('Equipment assigned. Check your rune supplies.');}
 else if(a==='unequip'){M.equip(s,s.wizards.find(w=>w.id===id),null,el.dataset.slot);}
 else if(a==='retire'){if(M.age(s,s.wizards.find(w=>w.id===id))<50)throw Error('Voluntary retirement opens at age 50. Normal retirement occurs around 60.');confirmPanel('Retire '+s.wizards.find(w=>w.id===id).name+'?','This is permanent. Their items return to storage and they become eligible for a limited faculty slot.','confirm-retire',`data-id="${id}"`);return;}
 else if(a==='confirm-retire'){M.retire(s,s.wizards.find(w=>w.id===id));route={type:'wizard',id};}
 else if(a==='induct'){const w=s.wizards.find(w=>w.id===id)||(historyWizard?.id===id?historyWizard:null);if(!w||w.hof||!qualifies(w))throw Error('That wizard is not eligible.');w.hof=true;s.prestige+=5;M.stat(s,null,'hall');M.news(s,`${w.name} enters the Hall of Names. A place in the academy forever.`,'hall');M.refreshRecords(s,w);}
 else if(a==='buy'){if(s.gold<100)throw Error('You need 100 gold.');s.gold-=100;const kind=el.dataset.kind;if(kind==='potions')s.potions+=5;else s.blanks+=20;}
 else if(a==='bind-seal'){if(s.gold<15||s.ingredients<3)throw Error('Requires 15 gold and 3 seal ingredients.');s.gold-=15;s.ingredients-=3;s.seals++;}
 else if(a==='event-choice'){T.resolveEvent(s,id,Number(el.dataset.index));}
 else if(a==='item-page'){inventory.page=Math.max(0,inventory.page+Number(el.dataset.dir));renderPanel();return;}
 else if(a==='archive-next'){archiveCursor=archivePage.next;await loadHistory(archiveType);return;}
 else if(a==='archive-first'){await loadHistory(archiveType,true);return;}
 else if(a==='history-wizard'){historyWizard=s.wizards.find(w=>w.id===id)||await archived('wizards',id);if(!historyWizard)throw Error('That record has not synced yet. Save, then try again.');route={type:'wizard',id};renderPanel();return;}
 else if(a==='item-history'){const it=await archived('items',id);if(!it)throw Error('That item record has not synced yet.');route={type:'item',id,item:it};renderPanel();return;}
 else if(a==='load-season'){const y=Number($('season-year').value);const season=await archived('seasons',`season_${String(y).padStart(6,'0')}`);if(!season)throw Error('That season is not finished or has not synced yet.');route={type:'season',season};renderPanel();return;}
 else if(a==='watch-last'){watchMatch(s.league.lastMatch);return;}
 else if(a==='load-match'){const m=await archived('matches',id);if(!m)throw Error('That match has not synced yet.');watchMatch(m);return;}
 else if(a==='replay-toggle'){watch.playing=!watch.playing;if(watch.index>=route.match.plays.length-1)watch.index=0;renderMatch();return;}
 else if(a==='replay-next'){watch.index=Math.min(watch.index+1,route.match.plays.length-1);renderMatch();return;}
 else if(a==='replay-end'){watch.index=route.match.plays.length-1;watch.playing=false;renderMatch();return;}
 else if(a==='save'){await checkpoint(true);toast(P.cloudStatus);return;}
 else if(a==='export'){toast('Preparing the complete academy archive…');const text=await P.exportBackup(s);download(text,`${s.name.replace(/[^a-z0-9-]/gi,'-')}-year-${M.year(s)}-backup.json`);toast('Backup downloaded.');return;}
 else if(a==='device-recovery'){const previous=await P.previousDeviceSave();if(!previous)throw Error('No superseded device snapshot is stored here.');download(JSON.stringify({format:'wizard-academy-backup',version:1,state:previous,archives:Object.values(previous.pending||{})},null,2),'previous-device-snapshot.json');toast('Snapshot exported; the full history remains in your cloud account.');return;}
 else if(a==='import'){const file=$('import-file').files[0];if(!file)throw Error('Choose a backup file first.');s=await P.importLocalBackup(file);route=null;$('panel').close();renderMain();toast('Local academy restored.');return;}
 else if(a==='logout'){await checkpoint(true);await P.signOut();localStorage.removeItem('wa-mode');authScreen();return;}
 else if(a==='reload'){location.reload();return;}
 M.shelveOverflow(s);M.checkAchievements(s);await checkpoint(['expedition','advance','return-home','retreat','room-choice','recruit','confirm-sell','confirm-retire','retrieve','induct'].includes(a));renderMain();if(route&&['room','wizard','item','combat','events'].includes(route.type))renderPanel();}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-act]');if(!el||busy)return;busy=true;try{await action(el);}catch(err){toast(errorMessage(err));if($('auth-status'))$('auth-status').textContent=errorMessage(err);}finally{busy=false;}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const btn=e.target.querySelector('button');if(btn)btn.disabled=true;try{if(e.target.id==='auth-form'){const u=await P.authenticate($('email').value.trim(),$('password').value,authMode==='signup');await enterAccount(u.uid);}else if(e.target.id==='found-form'){const name=$('academy-name').value.trim();if(!name)throw Error('Your academy needs a name.');s=M.makeGame(name);L.createLeague(s);await checkpoint(true);renderMain();}}catch(err){toast(errorMessage(err));if($('auth-status'))$('auth-status').textContent=errorMessage(err);}finally{busy=false;if(btn)btn.disabled=false;}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='equip-target'){route.target=el.value;$('item-comparison').innerHTML=comparison(s.items.find(i=>i.id===route.id),el.value);return;}if(el.id==='item-search'){inventory.search=el.value;inventory.page=0;renderPanel();return;}const what=el.dataset.change;if(!what||!s)return;try{if(P.conflicted)throw Error('Reload the cloud save before making changes.');const w=s.wizards.find(w=>w.id===el.dataset.id);T.processTime(s,Date.now());if(what==='job')M.assign(s,w,el.value);else if(what==='position'||what==='directive'){if(s.expedition?.ids.includes(w.id))throw Error('Prepare this at the academy.');w[what]=el.value;}else if(what==='rune-tier'){w.runeTier=Number(el.value);w.progress=0;}else if(what==='faculty'){if(el.value){const f=s.wizards.find(w=>w.id===el.value);if(!['Retired','Faculty'].includes(f.status))throw Error('Only retired wizards can teach.');for(const [room,id] of Object.entries(s.faculty))if(id===f.id)delete s.faculty[room];const old=s.wizards.find(w=>w.id===s.faculty[el.dataset.room]);if(old)old.status='Retired';s.faculty[el.dataset.room]=f.id;f.status='Faculty';M.stat(s,null,'faculty');M.news(s,`${f.name} is appointed professor of ${ROOMS.find(r=>r.id===el.dataset.room).name}.`,'faculty');}else{const old=s.wizards.find(w=>w.id===s.faculty[el.dataset.room]);if(old)old.status='Retired';delete s.faculty[el.dataset.room];}}else if(what==='lineup'||what==='bench'){const i=Number(el.dataset.index),val=el.value||null;for(const list of [s.lineup,s.bench])for(let j=0;j<list.length;j++)if(val&&list[j]===val)list[j]=null;s[what][i]=val;}else if(what==='tactics')s.tactics[el.dataset.key]=el.value;else if(what==='motion')s.settings.motion=el.value==='yes';else if(what==='farm-floor'||what==='boss-floor'){const f=Number(el.value);if(!Number.isInteger(f)||f<1||f>s.depth||(what==='boss-floor'&&f%10!==0)||(what==='farm-floor'&&f%10===0))throw Error('Choose a cleared floor of the correct kind.');s[what==='farm-floor'?'farmFloor':'bossFloor']=f;}else if(what==='inventory'){inventory[el.dataset.key]=el.value;inventory.page=0;}else if(what==='record')recordFilters[el.dataset.key]=el.value;await checkpoint();renderPanel();}catch(err){toast(errorMessage(err));renderPanel();}});
$('panel').addEventListener('cancel',()=>{route=null;watch.playing=false;});
$('panel').addEventListener('click',e=>{if(e.target===$('panel')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){$('panel').close();route=null;}}});
let lastCombatState=null,pointerHeld=false;
document.addEventListener('pointerdown',()=>{pointerHeld=true;});document.addEventListener('pointerup',()=>{pointerHeld=false;});document.addEventListener('pointercancel',()=>{pointerHeld=false;});
setInterval(()=>{if(!s||P.conflicted||busy)return;const now=performance.now(),dt=Math.min(.25,(now-lastTick)/1000);lastTick=now;if(document.hidden)return;try{const wall=Date.now();if(wall-s.lastWall>=5000){const report=T.processTime(s,wall);if(report.elapsed>120000)showReport(report);}if(s.combat?.state==='fighting'&&s.expedition){advanceCombatPlayback(s,dt,C.stepCombat);}updateTaskViews();if(s.combat&&route?.type==='combat'&&!pointerHeld){updateCombatView();}const state=s.combat?.state;if(state!==lastCombatState){lastCombatState=state;if(state==='victory'||state==='defeat')checkpoint(true);}
 if(watch.playing&&route?.type==='match'&&now-watch.at>1500){watch.at=now;watch.index=Math.min(watch.index+1,route.match.plays.length-1);if(watch.index===route.match.plays.length-1)watch.playing=false;renderMatch();}if(now-lastRail>10000){lastRail=now;updateHUD();renderRail();if(!pointerHeld&&!['INPUT','SELECT','BUTTON'].includes(document.activeElement?.tagName)&&route?.type==='room'&&['training','runes','infirmary','garden','observatory'].includes(route.id)){const scroll=$('panel-body').scrollTop;renderPanel();$('panel-body').scrollTop=scroll;}}if(now-localAt>(s.combat?.state==='fighting'?2500:10000)){localAt=now;checkpoint();}if(now-cloudAt>60000){cloudAt=now;checkpoint(true);}}catch(e){toast(errorMessage(e));}},250);
document.addEventListener('visibilitychange',()=>{if(!s)return;if(document.hidden){P.saveLocal(s).catch(e=>toast(errorMessage(e)));if(P.account!=='local')P.saveCloud(s).catch(()=>{});}else{lastTick=performance.now();if(!P.conflicted){const r=T.processTime(s);renderMain();if(r.elapsed>120000)showReport(r);checkpoint();}}});
window.addEventListener('pagehide',()=>{if(s)P.saveLocal(s).catch(()=>{});});
async function boot(){try{await P.openDB();startScene(()=>s);startCombatArena(()=>route?.type==='combat'?s:null);if(localStorage.getItem('wa-mode')==='local')await enterAccount('local');else if(localStorage.getItem('wa-mode')==='cloud'){await P.connect();if(P.authUser)await enterAccount(P.authUser.uid);else authScreen();}else authScreen();}catch(e){authScreen();$('auth-status').textContent=errorMessage(e);}}
boot();
